import{_ as l,a0 as r,w as d,s as u,I as e,x as t,a1 as n,A as o,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"10個調整讓Ubuntu賓至如歸 | LCTT x X-CMD","titleTemplate":false,"description":"10個調整讓Ubuntu賓至如歸 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10個調整讓Ubuntu賓至如歸 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10個調整讓Ubuntu賓至如歸 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140811 10 More Tweaks To Make Ubuntu Feel Like Home","title":"10個調整讓Ubuntu賓至如歸","tag":"201408","desc":""},"relativePath":"201408/20140811 10 More Tweaks To Make Ubuntu Feel Like Home.md","filePath":"[post].md"}'),s={name:"201408/20140811 10 More Tweaks To Make Ubuntu Feel Like Home.md"};function m(b,a,f,k,h,g){const p=r("Link");return d(),u("div",null,[a[21]||(a[21]=e("h1",{id:"_10個調整讓ubuntu賓至如歸",tabindex:"-1"},[t("10個調整讓Ubuntu賓至如歸 "),e("a",{class:"header-anchor",href:"#_10個調整讓ubuntu賓至如歸","aria-label":"Permalink to “10個調整讓Ubuntu賓至如歸”"},"​")],-1)),a[22]||(a[22]=e("p",null,[e("img",{src:"http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2014/08/ubuntu-home-840x420.jpg?15f1a2",alt:""})],-1)),e("p",null,[a[1]||(a[1]=t("不久前我提供給大家",-1)),n(p,{href:"http://www.makeuseof.com/tag/11-tweaks-perform-ubuntu-installation/"},{default:o(()=>[...a[0]||(a[0]=[t("12個調整Ubuntu的小建議",-1)])]),_:1}),a[2]||(a[2]=t("。 然而，已經是一段時間以前的事情了，現在我們又提出了另外10個建議，能夠使你的Ubuntu賓至如歸。",-1))]),a[23]||(a[23]=e("p",null,"這10個建議執行起來十分簡單方便，那就讓我們開始吧！",-1)),a[24]||(a[24]=e("h3",{id:"_1-安裝-tlp",tabindex:"-1"},[t("1. 安裝 TLP "),e("a",{class:"header-anchor",href:"#_1-安裝-tlp","aria-label":"Permalink to “1. 安裝 TLP”"},"​")],-1)),a[25]||(a[25]=e("p",null,[e("img",{src:"http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2014/01/tlp_stat.jpg?15f1a2",alt:""})],-1)),e("p",null,[n(p,{href:"http://www.makeuseof.com/tag/easily-increase-battery-life-tlp-linux/"},{default:o(()=>[...a[3]||(a[3]=[t("我們不久前涉及到了TLP",-1)])]),_:1}),a[4]||(a[4]=t(", 這是一款優化電源設置的軟件，可以讓你享受更長的電池壽命。之前我們深入的探討過TLP， 並且我們也在列表中提到這軟件真不錯。要安裝它，在終端運行以下命令：",-1))]),a[26]||(a[26]=i(`<pre><code>sudo add-apt-repository -y ppa:linrunner/tlp &amp;&amp; sudo apt-get update &amp;&amp; sudo apt-get install -y tlp tlp-rdw tp-smapi-dkms acpi-call-tools &amp;&amp; sudo tlp start
</code></pre><p>上面的命令將添加必要的倉庫，更新包的列表以便它能包含被新倉庫提供的包，安裝TLP並且開啓這個服務。</p><h3 id="_2-系統負載指示器" tabindex="-1">2. 系統負載指示器 <a class="header-anchor" href="#_2-系統負載指示器" aria-label="Permalink to “2. 系統負載指示器”">​</a></h3><p><img src="http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2014/07/ubuntu_tweak_systemload.jpg?15f1a2" alt=""></p><p>給你的Ubuntu桌面添加一個系統負載指示器能讓你快速瞭解到你的系統資源佔用率。 如果你不想在桌面上添加這個技術圖表，那麼可以不要添加， 但是對於那些對它感興趣的人來説，這個擴展真是很好。 你可以運行這個命令去安裝它：</p><pre><code>sudo apt-get install indicator-multiload
</code></pre><p>然後在Dash裏面找到它並且打開。</p><h3 id="_3-天氣指示器" tabindex="-1">3. 天氣指示器 <a class="header-anchor" href="#_3-天氣指示器" aria-label="Permalink to “3. 天氣指示器”">​</a></h3><p><img src="http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2014/07/ubuntu_tweak_weatherind.jpg?15f1a2" alt=""></p><p>Ubuntu過去提供內置的天氣指示器，但是自從它切換到Gnome 3以後，就不再默認提供了。你需要安裝一個獨立的指示器來代替。 你可以通過以下命令安裝它：</p><pre><code>sudo add-apt-repository -y ppa:atareao/atareao &amp;&amp; sudo apt-get update &amp;&amp; sudo apt-get install -y my-weather-indicator
</code></pre><p>這將添加另外一個倉庫，更新包的列表，並且安裝這個指示器。然後在Dash裏面找到並開啓它。</p><h3 id="_4-安裝-dropbox-或其他雲存儲解決方案" tabindex="-1">4. 安裝 Dropbox 或其他雲存儲解決方案 <a class="header-anchor" href="#_4-安裝-dropbox-或其他雲存儲解決方案" aria-label="Permalink to “4. 安裝 Dropbox 或其他雲存儲解決方案”">​</a></h3><p><img src="http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2014/05/Dropbox-2.png?15f1a2" alt=""></p><p>我在我所有的Linux系統裏面都安裝過的一個軟件，那就是Dropbox。沒有它，真的就找不到家的感覺，主要是因為我所有經常使用的文件都儲存在Dropbox中。安裝Dropbox非常直截了當，但是要花點時間執行一個簡單的命令。 在開始之前，為了你能在系統托盤裏看到Dropbox的圖標，你需要運行這個命令：</p><pre><code>sudo apt-get install libappindicator1
</code></pre><p>然後你需要去Dropbox的下載頁面，接着安裝你已下載的.deb文件。現在你的Dropbox應該已經運行了。</p>`,17)),e("p",null,[a[6]||(a[6]=t("如果你有點討厭Dropbox, 你也可以嘗試使用Copy ",-1)),n(p,{href:"http://www.makeuseof.com/tag/synchronize-files-ubuntu-onedrive/"},{default:o(()=>[...a[5]||(a[5]=[t("或者OneDrive",-1)])]),_:1}),a[7]||(a[7]=t("。兩者提供更多免費存儲空間，這是考慮使用它們的很大一個原因。比起OneDrive我更推薦使用Copy，因為Copy能工作在所有的Linux發行版上。",-1))]),a[27]||(a[27]=i(`<h3 id="_5-安裝pidgin和skype" tabindex="-1">5. 安裝Pidgin和Skype <a class="header-anchor" href="#_5-安裝pidgin和skype" aria-label="Permalink to “5. 安裝Pidgin和Skype”">​</a></h3><p><img src="http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2013/12/skype_linux_conversation.jpg?15f1a2" alt=""></p><p>和朋友們保持聯繫特別好，並且如果你使用即時通訊，那麼你很幸運。 Pidgin和Skype在Linux都十分出色，它們都能連接所有主要網絡。安裝Pidgin就像運行這個命令一樣簡單：</p><pre><code>sudo apt-get install pidgin
</code></pre><p>安裝Skype也很簡單 — 你僅僅需要去Skype的下載頁面並且下載你Ubuntu12.04對應架構的.deb文件就可以了。</p><h3 id="_6-移除鍵盤指示器" tabindex="-1">6. 移除鍵盤指示器 <a class="header-anchor" href="#_6-移除鍵盤指示器" aria-label="Permalink to “6. 移除鍵盤指示器”">​</a></h3><p><img src="http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2014/07/ubuntu_tweak_keyboard_indicator.jpg?15f1a2" alt=""></p><p>在桌面上顯示鍵盤指示器可能讓一些人很苦惱。對於講英語的人來説，它僅僅顯示一個“EN”，這可能是惱人的，因為很多人不需要改變鍵盤佈局或者被提醒他們正在使用英語。要移除這個指示器，選擇系統設置，然後文本輸入，接着去掉“在菜單欄顯示當前輸入源”的勾。 （譯註:國人可能並不適合這個建議。）</p><h3 id="_7-迴歸傳統菜單" tabindex="-1">7. 迴歸傳統菜單### <a class="header-anchor" href="#_7-迴歸傳統菜單" aria-label="Permalink to “7. 迴歸傳統菜單###”">​</a></h3><p><img src="http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2014/07/ubuntu_tweak_classicmenu.jpg?15f1a2" alt=""></p><p>在Ubuntu切換到Unity之前，它使用Gnome 2 作為默認的桌面環境。 這包含一個簡單的菜單去訪問已安裝的應用，菜單包含的很多分類，比如： 遊戲，辦公， 互聯網，等等。 你可以用另外一個簡單的包找回這個“傳統菜單” 。要安裝它，運行這個命令：</p><pre><code>sudo add-apt-repository -y ppa:diesch/testing &amp;&amp; sudo apt-get update &amp;&amp; sudo apt-get install -y classicmenu-indicator
</code></pre><h3 id="_8-安裝flash和java" tabindex="-1">8. 安裝Flash和Java <a class="header-anchor" href="#_8-安裝flash和java" aria-label="Permalink to “8. 安裝Flash和Java”">​</a></h3><p>在之前的文章中我提到了安裝解碼器和Silverlight，我應該也提到了Flash和Java是它們所需要的主要插件，雖然有時可能它們可能被遺忘。要安裝它們只需運行這個命令：</p><pre><code>sudo add-apt-repository -y ppa:webupd8team/java &amp;&amp; sudo apt-get update &amp;&amp; sudo apt-get install oracle-java7-installer flashplugin-installer
</code></pre><p>安裝Java需要新增倉庫，因為Ubuntu不再包含它的專利版本（大多數人為了最好的性能推薦使用這個版本），而是使用開源的OpenJDK。</p><h3 id="_9-安裝vlc" tabindex="-1">9. 安裝VLC <a class="header-anchor" href="#_9-安裝vlc" aria-label="Permalink to “9. 安裝VLC”">​</a></h3><p><img src="http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2014/07/ubuntu_tweaks_vlc.jpg?15f1a2" alt=""></p><p>默認的媒體播放器Totem十分優秀但是它依賴很多獨立安裝的解碼器才能很好的工作。我個人推薦你安裝VLC媒體播放器， 因為它包含所有解碼器並且實際上它支持世界上每一種媒體格式。要安裝它，僅僅需要運行如下命令：</p><pre><code>sudo apt-get install vlc
</code></pre><h3 id="_10-安裝putty-或者不" tabindex="-1">10. 安裝PuTTY (或者不) <a class="header-anchor" href="#_10-安裝putty-或者不" aria-label="Permalink to “10. 安裝PuTTY (或者不)”">​</a></h3><p><img src="http://main.makeuseoflimited.netdna-cdn.com/wp-content/uploads/2014/07/ubuntu_tweaks_putty.jpg?15f1a2" alt=""></p><p>最近，如果你出於SSH的需要而使用PuTTY，你有兩個選擇：為Linux安裝PuTTY，或者直接使用終端。如果你想使用終端安裝PuTTY，需要用到這個命令：</p><pre><code>sudo apt-get install putty
</code></pre><p>然而，並不需要直接安裝它，因為你可以使用這個命令來連接任何遠程主機。</p><pre><code>ssh username@this.domain.here
</code></pre><p>用你想要連接的用户名來替換掉“username”，然後用主機的直接域名或者IP地址替換掉“this.domain.here” 都可以。</p><h3 id="你推薦如何調整" tabindex="-1">你推薦如何調整？ <a class="header-anchor" href="#你推薦如何調整" aria-label="Permalink to “你推薦如何調整？”">​</a></h3><p>補充了這10個調整，你應該感覺你的Ubuntu真的有家的感覺，這很容易建立起或擊潰你的Linux體驗。有許多不同的方式去定製你自己的體驗去讓它更適合你的需要；你只需自己尋找來發現你想要的東西。</p><p><strong>您有什麼其它的調整和建議想和讀者分享？</strong>在評論中告訴我們吧！</p><p><em>圖片致謝: Home doormat Via Shutterstock</em></p><hr>`,32)),e("p",null,[a[9]||(a[9]=t("via: ",-1)),n(p,{href:"http://www.makeuseof.com/tag/10-tweaks-make-ubuntu-feel-like-home/"},{default:o(()=>[...a[8]||(a[8]=[t("http://www.makeuseof.com/tag/10-tweaks-make-ubuntu-feel-like-home/",-1)])]),_:1})]),e("p",null,[a[13]||(a[13]=t("作者：",-1)),n(p,{href:"http://www.makeuseof.com/tag/author/danny/"},{default:o(()=>[...a[10]||(a[10]=[t("Danny Stieben",-1)])]),_:1}),a[14]||(a[14]=t(" 譯者：",-1)),n(p,{href:"https://github.com/guodongxiaren"},{default:o(()=>[...a[11]||(a[11]=[t("guodongxiaren",-1)])]),_:1}),a[15]||(a[15]=t(" 校對：",-1)),n(p,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...a[12]||(a[12]=[t("Caroline",-1)])]),_:1})]),e("p",null,[a[18]||(a[18]=t("本文由 ",-1)),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[16]||(a[16]=[t("LCTT",-1)])]),_:1}),a[19]||(a[19]=t(" 原創翻譯，",-1)),n(p,{href:"http://linux.cn/"},{default:o(()=>[...a[17]||(a[17]=[t("Linux中國",-1)])]),_:1}),a[20]||(a[20]=t(" 榮譽推出",-1))])])}const _=l(s,[["render",m]]);export{x as __pageData,_ as default};
